import json
with open('/root/DATA/products/CoachForce.json') as f:
    data = json.load(f)

# Check meeting chats
chats = data.get('meeting_chats', [])
print(f'Total meeting chats: {len(chats)}')
for i, chat in enumerate(chats):
    print(f'\n=== Chat {i} ===')
    if isinstance(chat, dict):
        for k in chat.keys():
            if k == 'messages':
                print(f'  messages: {len(chat["messages"])} messages')
                for m in chat["messages"][:3]:
                    print(f'    {m}')
            else:
                val = str(chat[k])[:200]
                print(f'  {k}: {val}')
    else:
        print(f'  Type: {type(chat)}, preview: {str(chat)[:200]}')
EOF

